code.bad:
CREATE TABLE items (
  cve TEXT,
  cvss REAL            -- score only: cannot explain or convert
);

CREATE TABLE items (
  cve TEXT PRIMARY KEY   -- other identifiers have nowhere to live
);

code.good:
CREATE TABLE items (
  cve TEXT PRIMARY KEY,
  vendor_id TEXT           -- e.g. a vendor advisory id
);

CREATE TABLE item_aliases (
  cve   TEXT NOT NULL,
  alias TEXT NOT NULL,
  kind  TEXT NOT NULL,     -- ghsa / osv / vendor / cwe
  PRIMARY KEY (cve, alias)
);
